const tf = require('@tensorflow/tfjs');

(async () => {
  await tf.setBackend('cpu');
  await tf.ready();

  // --- 1. Does minimize return null when returnCost=false? ---
  const v = tf.variable(tf.tensor1d([1, 2, 3]));
  const opt = tf.train.adam(0.1);
  const ret = opt.minimize(() => tf.tidy(() => v.square().sum()), false, [v]);
  console.log('minimize(fn, false, [v]) returns:', ret === null ? 'null' : typeof ret);
  try {
    ret.dispose();
    console.log('  .dispose() on the result: OK');
  } catch (e) {
    console.log('  .dispose() on the result THROWS:', e.message);
  }
  v.dispose();

  // --- 2. Init sizes on the real dataset ---
  const NUM_USERS = 943, MAX_MOVIE = 1682, F = 16;
  const globalMean = 3.5806026199776437; // computed from the real train split
  tf.util.seed(42);
  const userFactors = tf.variable(tf.randomNormal([NUM_USERS + 1, F], 0, 0.05));
  const itemFactors = tf.variable(tf.randomNormal([MAX_MOVIE + 1, F], 0, 0.05));

  const nParams = (NUM_USERS + 1 + MAX_MOVIE + 1) * F;
  const sumSq = tf.tidy(() => userFactors.square().sum().add(itemFactors.square().sum()));
  const ss = await sumSq.data();

  // Batch MSE at init: simulate a batch of 64 real ratings around globalMean.
  const targets = tf.tensor1d([5,4,4,3,5,3,2,4,5,5,1,3,4,2,5,4,3,3,5,4,4,2,5,3,4,5,1,2,4,3,5,4,
                               5,4,4,3,5,3,2,4,5,5,1,3,4,2,5,4,3,3,5,4,4,2,5,3,4,5,1,2,4,3,5,4]);
  const mse = tf.tidy(() => tf.losses.meanSquaredError(targets, targets.mul(0).add(globalMean)));

  for (const reg of [0.05]) {
    const l2 = ss[0] * reg;
    const mseVal = (await mse.data())[0];
    console.log('\n=== INITIAL LOSS COMPOSITION (reg=' + reg + ', batch=64) ===');
    console.log('factor params                       :', nParams);
    console.log('sum of squared factor entries       :', ss[0].toFixed(4));
    console.log('L2 term = reg * sumSq                :', l2.toFixed(4));
    console.log('batch MSE (pred=globalMean)          :', mseVal.toFixed(4));
    console.log('L2 / batchMSE                        :', (l2 / mseVal).toFixed(3));
    console.log('batches per epoch (79619/64)         :', Math.ceil(79619 / 64));
    console.log('L2 applied per epoch (batches)       :', Math.ceil(79619 / 64));
