const fs = require('fs');
const tf = require('@tensorflow/tfjs');
const WEEK5 = '/Users/anastasiazaporozec/Desktop/RecSys-LLMs/week5';

const dataSrc = fs.readFileSync(WEEK5 + '/data.js', 'utf8');
const moviesText = fs.readFileSync(WEEK5 + '/u.item', 'utf8');
const ratingsText = fs.readFileSync(WEEK5 + '/u.data', 'utf8');
const accessor = `;globalThis.__data = { movies(){return movies;}, ratings(){return ratings;},
  load(mt,rt){parseItemData(mt);parseRatingData(rt);numUsers=ratings.reduce((m,r)=>Math.max(m,r.userId),0);numMovies=movies.length;buildRatingMatrix();},
  splitByTimestamp, get numUsers(){return numUsers;} };`;
eval(dataSrc + accessor);
const D = globalThis.__data;
D.load(moviesText, ratingsText);
const { train, val, test } = D.splitByTimestamp();
const numUsers = D.numUsers;
const movies = D.movies();
const maxMovieId = movies.reduce((m, x) => Math.max(m, x.id), 0);
const F = 16;
const globalMean = train.reduce((a, r) => a + r.rating, 0) / train.length;

function idxArrays(split) {
  const n = split.length;
  const u = new Int32Array(n), i = new Int32Array(n), t = new Float32Array(n);
  for (let k = 0; k < n; k++) { u[k] = split[k].userId; i[k] = split[k].movieId; t[k] = split[k].rating; }
  return { u, i, t, n };
}
function rmse(model, arr) {
  return tf.tidy(() => {
    const u = tf.gather(model.userFactors, tf.tensor1d(arr.u, 'int32'));
    const i = tf.gather(model.itemFactors, tf.tensor1d(arr.i, 'int32'));
    const dot = tf.sum(tf.mul(u, i), 1);
    const pred = tf.clipByValue(dot.add(model.globalMean), 1, 5);
    const diff = pred.sub(tf.tensor1d(arr.t, 'float32'));
    return Math.sqrt(tf.mean(diff.square()).dataSync()[0]);
  });
}
function norm(model) {
  return tf.tidy(() => {
    const s = model.userFactors.square().sum().add(model.itemFactors.square().sum());
    return Math.sqrt(s.dataSync()[0]);
  });
}

(async () => {
  await tf.setBackend('cpu'); await tf.ready();
  const trainArr = idxArrays(train), valArr = idxArrays(val), testArr = idxArrays(test);
  const baseVal = Math.sqrt(val.reduce((a, r) => a + (globalMean - r.rating) ** 2, 0) / val.length);
  const baseTest = Math.sqrt(test.reduce((a, r) => a + (globalMean - r.rating) ** 2, 0) / test.length);
  console.log('globalMean', globalMean, 'baseline val', baseVal, 'baseline test', baseTest);

  const model = {
    userFactors: tf.variable(tf.randomNormal([numUsers + 1, F], 0, 0.05)),
    itemFactors: tf.variable(tf.randomNormal([maxMovieId + 1, F], 0, 0.05)),
    globalMean,
  };

  const lr = 0.01, reg = 0.05, batchSize = 64, epochs = Number(process.argv[2] || 5);
  const optimizer = tf.train.adam(lr);
  const order = [...Array(train.length).keys()];
  console.log('init: trainRMSE', rmse(model, trainArr).toFixed(4), 'valRMSE', rmse(model, valArr).toFixed(4), '||P,Q||', norm(model).toFixed(3));

  for (let epoch = 1; epoch <= epochs; epoch++) {
    for (let s = 0; s < order.length; s += batchSize) {
      const b = order.slice(s, s + batchSize);
      const bu = tf.tensor1d(b.map(k => trainArr.u[k]), 'int32');
      const bi = tf.tensor1d(b.map(k => trainArr.i[k]), 'int32');
      const bt = tf.tensor1d(b.map(k => trainArr.t[k]), 'float32');
      // Mirrors the suggested snippet; the suggested `.dispose()` is omitted
      // because minimize(...,false,...) returns null (it would throw).
      optimizer.minimize(() => tf.tidy(() => {
        const u = tf.gather(model.userFactors, bu);
        const i = tf.gather(model.itemFactors, bi);
        const pred = tf.sum(u.mul(i), 1).add(model.globalMean);
        const mse = tf.losses.meanSquaredError(bt, pred);
        const l2 = model.userFactors.square().sum().add(model.itemFactors.square().sum()).mul(reg);
        return mse.add(l2);
      }), false, [model.userFactors, model.itemFactors]);
      bu.dispose(); bi.dispose(); bt.dispose();
    }
    console.log(`epoch ${epoch}: trainRMSE ${rmse(model, trainArr).toFixed(4)} valRMSE ${rmse(model, valArr).toFixed(4)} ||P,Q|| ${norm(model).toFixed(3)}`);
  }
  console.log('final: testRMSE', rmse(model, testArr).toFixed(4), '(baseline test', baseTest.toFixed(4) + ')');
})();

