const fs = require('fs');
const tf = require('@tensorflow/tfjs');
const WEEK5 = '/Users/anastasiazaporozec/Desktop/RecSys-LLMs/week5';

global.tf = tf;
global.window = {};
const fakeEl = { textContent: '' };
global.document = {
  getElementById: () => null,
  createElement: () => ({ style: {}, appendChild() {}, insertBefore() {} }),
  body: { insertBefore() {}, firstChild: null },
};

const dataSrc = fs.readFileSync(WEEK5 + '/data.js', 'utf8');
const scriptSrc = fs.readFileSync(WEEK5 + '/script.js', 'utf8');
const moviesText = fs.readFileSync(WEEK5 + '/u.item', 'utf8');
const ratingsText = fs.readFileSync(WEEK5 + '/u.data', 'utf8');

const MODE = process.argv[2] || 'correct';

// Implementations injected INTO the same eval scope as data.js + script.js.
const overrides = `
;globalThis.__run = async function(moviesText, ratingsText){
  // Load data exactly like loadData(), then split.
  parseItemData(moviesText);
  parseRatingData(ratingsText);
  numUsers = ratings.reduce((max,r)=>Math.max(max,r.userId),0);
  numMovies = movies.length;
  buildRatingMatrix();
  const sp = splitByTimestamp();
  trainSet = sp.train; valSet = sp.val; testSet = sp.test;
  return runTests({ set textContent(v){ this._t = v; }, get textContent(){ return this._t; } });
};
const MODE = ${JSON.stringify(MODE)};
function __init(train, numFactors){
  const gm = train.length ? train.reduce((a,r)=>a+r.rating,0)/train.length : 0;
  if (model) { model.userFactors.dispose(); model.itemFactors.dispose(); }
  const maxMovieId = movies.reduce((m,x)=>Math.max(m,x.id),0);
  model = {
    userFactors: tf.variable(tf.randomNormal([numUsers+1, numFactors],0,0.05)),
    itemFactors: tf.variable(tf.randomNormal([maxMovieId+1, numFactors],0,0.05)),
    globalMean: gm,
  };
  return model;
}
initializeFactors = function(train, numFactors = NUM_FACTORS){ return __init(train, numFactors); };

predictRating = function(userId, movieId){
  if (!model) return 0;
  const uRows = model.userFactors.shape[0], iRows = model.itemFactors.shape[0];
  if (userId<0||userId>=uRows||movieId<0||movieId>=iRows) return model.globalMean;
  if (MODE === 'degenerate') return clamp(model.globalMean, 1, 5);
  const f = model.userFactors.shape[1];
  return tf.tidy(()=>{
    const u = model.userFactors.slice([userId,0],[1,f]);
    const i = model.itemFactors.slice([movieId,0],[1,f]);
    const dot = u.mul(i).sum().dataSync()[0];
    return clamp(model.globalMean + dot, 1, 5);
  });
};

trainMF = function(train, val, opts){
  const history = trainingHistory; // append in place, like the suggested code
  if (train.length === 0) return history;
  const { epochs, lr, reg, batchSize } = opts;
  const optimizer = tf.train.adam(lr);
  const order = [...Array(train.length).keys()];
  for (let epoch=1; epoch<=epochs; epoch++){
    for (let s=0; s<order.length; s+=batchSize){
      const b = order.slice(s, s+batchSize);
      const bu = tf.tensor1d(b.map(k=>train[k].userId),'int32');
      const bi = tf.tensor1d(b.map(k=>train[k].movieId),'int32');
      const bt = tf.tensor1d(b.map(k=>train[k].rating),'float32');
      optimizer.minimize(()=>tf.tidy(()=>{
        const u = tf.gather(model.userFactors, bu);
        const i = tf.gather(model.itemFactors, bi);
        const pred = tf.sum(u.mul(i),1).add(model.globalMean);
        const mse = tf.losses.meanSquaredError(bt, pred);
        const l2 = model.userFactors.square().sum().add(model.itemFactors.square().sum()).mul(reg);
        return mse.add(l2);
      }), false, [model.userFactors, model.itemFactors]);
      bu.dispose(); bi.dispose(); bt.dispose();
    }
    history.push({ epoch, trainRMSE: computeRMSEFor(train), valRMSE: computeRMSEFor(val) });
  }
  return history;
};

selectBestCheckpoint = function(history){
  if (!history || history.length===0) return null;
  let best = history[0];
  for (const row of history) if (row.valRMSE < best.valRMSE) best = row;
  return best;
};

recommendTopK = function(userId, K = 10){
  if (!model || K<=0) return [];
  const f = model.userFactors.shape[1];
  const uRows = model.userFactors.shape[0];
  if (userId<0||userId>=uRows) return [];
  const rated = new Set();
  for (const r of trainSet) if (r.userId===userId) rated.add(r.movieId);
  for (const r of valSet) if (r.userId===userId) rated.add(r.movieId);
  const validIds = new Set(movies.map(m=>m.id));
  return tf.tidy(()=>{
    const rows = model.itemFactors.shape[0];
    const arr = new Float32Array(rows);
    if (MODE === 'degenerate'){
      for (let id=0; id<rows; id++) arr[id] = model.globalMean;
    } else {
      const userRow = model.userFactors.slice([userId,0],[1,f]);
      const scores = model.itemFactors.matMul(userRow,false,true).squeeze().add(model.globalMean);
      arr.set(scores.dataSync());
    }
    const cand = [];
    for (let id=0; id<rows; id++){
      if (!validIds.has(id) || rated.has(id)) continue;
      cand.push({ movieId:id, score:arr[id] });
    }
    cand.sort((a,b)=>b.score-a.score);
    return cand.slice(0,K).map(c=>({ movieId:c.movieId, title:movieTitle(c.movieId), score:c.score }));
  });
};

recallAtK = function(K = 10){
  const trainCandidates = new Set(trainSet.map(r=>r.movieId));
  const testUsers = new Set();
  const relevant = new Map();
  const unseen = new Set();
  for (const r of testSet){
    testUsers.add(r.userId);
    if (r.rating >= 4){
      if (!relevant.has(r.userId)) relevant.set(r.userId, new Set());
      relevant.get(r.userId).add(r.movieId);
      if (!trainCandidates.has(r.movieId)) unseen.add(r.movieId);
    }
  }
  const perUser = [];
  const usersWithoutRelevant = [];
  for (const uid of testUsers){
    const rel = [...(relevant.get(uid)||[])].filter(id=>trainCandidates.has(id));
    if (rel.length===0){ usersWithoutRelevant.push(uid); continue; }
    const recIds = new Set(recommendTopK(uid,K).map(x=>x.movieId));
    let hit = 0; for (const id of rel) if (recIds.has(id)) hit++;
    perUser.push({ userId:uid, relevant:rel.length, hit });
  }
  const overallRecall = perUser.length ? perUser.reduce((a,u)=>a+u.hit/u.relevant,0)/perUser.length : 0;
  return { overallRecall, perUser, excluded:{ unseenIds:[...unseen].sort((a,b)=>a-b), usersWithoutRelevant } };
};
`;

eval(dataSrc + '\n' + scriptSrc + overrides);

