  *  - The result is clamped to `[1, 5]`.
  *
  * @param {number} userId
  * @param {number} movieId
  * @returns {number} predicted rating in `[1, 5]`
  */
 function predictRating(userId, movieId) {
-  // TODO(hw5): gather the two factor rows, take their dot product, add
