const fs = require('fs');
const tf = require('@tensorflow/tfjs');
const WEEK5 = '/Users/anastasiazaporozec/Desktop/RecSys-LLMs/week5';

global.tf = tf;
global.window = {};
global.document = {
  getElementById: () => null,
  createElement: () => ({ style: {}, appendChild() {}, insertBefore() {} }),
  body: { insertBefore() {}, firstChild: null },
};

const dataSrc = fs.readFileSync(WEEK5 + '/data.js', 'utf8');
const scriptSrc = fs.readFileSync(WEEK5 + '/script.js', 'utf8');
const moviesText = fs.readFileSync(WEEK5 + '/u.item', 'utf8');
const ratingsText = fs.readFileSync(WEEK5 + '/u.data', 'utf8');

// Accessors appended into the same eval scope as data.js + script.js.
const accessor = `
;function __factorStats(){
  return tf.tidy(()=>{
    const uSum = model.userFactors.abs().sum().dataSync()[0];
    const iSum = model.itemFactors.abs().sum().dataSync()[0];
    const total = model.userFactors.size + model.itemFactors.size;
    return { userMeanAbs:uSum/model.userFactors.size, itemMeanAbs:iSum/model.itemFactors.size, combinedMeanAbs:(uSum+iSum)/total };
  });
}
globalThis.__h = {
  load(mt, rt){
    parseItemData(mt); parseRatingData(rt);
    numUsers = ratings.reduce((m,r)=>Math.max(m,r.userId),0);
    numMovies = movies.length; buildRatingMatrix();
    const sp = splitByTimestamp();
    trainSet = sp.train; valSet = sp.val; testSet = sp.test;
    return { train:trainSet.length, val:valSet.length, test:testSet.length, globalMean: trainSet.reduce((a,r)=>a+r.rating,0)/trainSet.length };
  },
  runTests(el){ return runTests(el); },
  baselineVal(){ return computeBaselineRMSE(valSet); },
  baselineTest(){ return computeBaselineRMSE(testSet); },
  baselineTrain(){ return computeBaselineRMSE(trainSet); },
  train(epochs){
    const opts = { epochs, lr:0.01, reg:0.05, batchSize:64 };
    initializeFactors(trainSet, NUM_FACTORS);
    const t0 = Date.now();
    trainingHistory = trainMF(trainSet, valSet, opts);
    const elapsed = (Date.now()-t0)/1000;
    bestCheckpoint = selectBestCheckpoint(trainingHistory);
    return {
      history: trainingHistory.slice(),
      best: bestCheckpoint,
      elapsedSeconds: elapsed,
      trainRMSE: computeRMSEFor(trainSet),
      valRMSE: computeRMSEFor(valSet),
      testRMSE: computeRMSEFor(testSet),
      factors: __factorStats(),
    };
  },
  recommend(userId, K){ return recommendTopK(userId, K); },
  recall(K){ return recallAtK(K); },
};
`;

eval(dataSrc + '\n' + scriptSrc + accessor);

