 /**
  * Escape text before inserting it into HTML.
  *
  * @param {string} text
  * @returns {string}
  */
 function escapeHtml(text) {
   return String(text)
     .replace(/&/g, "&amp;")
     .replace(/</g, "&lt;")
     .replace(/>/g, "&gt;")
     .replace(/"/g, "&quot;")
     .replace(/'/g, "&#39;");
 }

 /**
  * Clamp a number into the inclusive range `[lo, hi]`.
  *
  * @param {number} value
  * @param {number} lo
  * @param {number} hi
  * @returns {number}
  */
 function clamp(value, lo, hi) {
