const fs = require('fs');
const tf = require('@tensorflow/tfjs');
const WEEK5 = '/Users/anastasiazaporozec/Desktop/RecSys-LLMs/week5';

global.tf = tf;
global.window = {};
global.document = {
  getElementById: () => null,
  createElement: () => ({ style: {}, appendChild() {}, insertBefore() {} }),
  body: { insertBefore() {}, firstChild: null },
};

const dataSrc = fs.readFileSync(WEEK5 + '/data.js', 'utf8');
const scriptSrc = fs.readFileSync(WEEK5 + '/script.js', 'utf8');
const moviesText = fs.readFileSync(WEEK5 + '/u.item', 'utf8');
const ratingsText = fs.readFileSync(WEEK5 + '/u.data', 'utf8');

const accessor = `
;globalThis.__h = {
  load(mt, rt){
    parseItemData(mt); parseRatingData(rt);
    numUsers = ratings.reduce((m,r)=>Math.max(m,r.userId),0);
    numMovies = movies.length; buildRatingMatrix();
    const sp = splitByTimestamp();
    trainSet = sp.train; valSet = sp.val; testSet = sp.test;
    return { train:trainSet.length, val:valSet.length, test:testSet.length };
  },
};
`;
eval(dataSrc + '\n' + scriptSrc + accessor);

(async () => {
  await tf.setBackend('cpu'); await tf.ready();
  const H = globalThis.__h;
  H.load(moviesText, ratingsText);

  // Print history for users 1 and 36
  for (const userId of [1, 36]) {
    const userTrainVal = [...trainSet, ...valSet].filter((r) => r.userId === userId);
    console.log(`\n=== User ${userId} ===`);
    console.log(`Train+Val ratings: ${userTrainVal.length}`);

    const genreCounts = new Map();
    for (const r of userTrainVal) {
      const movie = movies.find((m) => m.id === r.movieId);
      if (movie) {
        for (const g of movie.genres) {
          genreCounts.set(g, (genreCounts.get(g) || 0) + 1);
        }
      }
    }
    const topGenres = [...genreCounts.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5)
      .map(([g, c]) => `${g} (${c})`)
      .join(', ') || '—';
    console.log(`Top genres: ${topGenres}`);

    const topRated = userTrainVal
      .sort((a, b) => b.rating - a.rating)
      .slice(0, 10)
      .map((r) => {
        const movie = movies.find((m) => m.id === r.movieId);
        const genres = movie ? movie.genres.join(', ') : '—';
